parameters.jsCode:
const raw = $json.output ?? $json.text ?? $json.response ?? '';
let d;
try {
  d = JSON.parse(String(raw).replace(/^```json\s*/i, '').replace(/```$/, '').trim());
} catch (e) {
  d = { status: 'error', respuesta: String(raw || 'No se pudo interpretar la respuesta del especialista.'), requires_human: true };
}
// Trazabilidad RAG: qué consultó el agente y qué fragmentos recuperó (los usa el juez del M8)
const pasos = Array.isArray($json.intermediateSteps) ? $json.intermediateSteps : [];
const consultas_rag = [];
const vistos = new Set();
const fragmentos = [];
for (const p of pasos) {
  if (p?.action?.tool !== 'consultar_manual_protable') continue;
  const ti = p.action.toolInput;
  consultas_rag.push(typeof ti === 'string' ? ti : (ti?.consulta ?? JSON.stringify(ti)));
  let o = p.observation;
  try { o = typeof o === 'string' ? JSON.parse(o) : o; } catch (e) { continue; }
  for (const x of (Array.isArray(o) ? o : [o])) {
    const res = x?.resultados ?? x?.json?.resultados ?? [];
    for (const f of res) {
      if (vistos.has(f.chunk_id)) continue;
      vistos.add(f.chunk_id);
      fragmentos.push({ chunk_id: f.chunk_id, seccion: f.seccion, titulo: f.titulo, score: f.score, contenido: f.contenido });
    }
  }
}
// Guardia determinística: si consultó el manual y no volvió ningún fragmento, la respuesta es la regla No sé
const NOSE = 'No sé: esa información no está en el manual de soporte de ProTable. Tu caso pasa a una persona del equipo, que lo va a revisar.';
if (consultas_rag.length > 0 && fragmentos.length === 0 && !String(d.respuesta ?? '').startsWith('No sé')) { d.respuesta = NOSE; d.requires_human = true; d.fuentes = []; }
// Guardia de abstención: si el modelo admite que el manual no trae el dato pero lo parafrasea, se normaliza a la frase literal
const ABSTENCION = /(el manual|la documentaci[oó]n|los fragmentos)[^.]{0,40}no (especifica|menciona|indica|informa|detalla|aclara|incluye|dice)|no (hay|tengo|encuentro) informaci[oó]n|no figura en el manual/i;
if (!String(d.respuesta ?? '').startsWith('No sé') && ABSTENCION.test(String(d.respuesta ?? ''))) { d.respuesta = NOSE; d.requires_human = true; d.fuentes = []; d.abstencion_normalizada = true; }
// Cita obligatoria: si la respuesta usó secciones del manual y no las nombra, se agrega la cita al final
{ const fv = (Array.isArray(d.fuentes) ? d.fuentes.map(String) : []).filter((s) => fragmentos.some((f) => f.seccion === s));
  if (fv.length && !String(d.respuesta ?? '').startsWith('No sé') && !/secci[oó]n/i.test(String(d.respuesta ?? ''))) { d.respuesta = String(d.respuesta).trim() + ' (Manual de soporte, ' + (fv.length > 1 ? 'secciones ' + fv.join(' y ') : 'sección ' + fv[0]) + ')'; d.cita_agregada = true; } }
return [{ json: {
  status: ['success', 'error'].includes(d.status) ? d.status : 'success',
  worker: 'SALES',
  respuesta: d.respuesta ?? '',
  requires_human: Boolean(d.requires_human),
  // Solo valen las citas de secciones que la herramienta devolvió de verdad
  fuentes: (Array.isArray(d.fuentes) ? d.fuentes.map(String) : []).filter((s) => fragmentos.some((f) => f.seccion === s)),
  cita_sin_respaldo: (Array.isArray(d.fuentes) ? d.fuentes.map(String) : []).some((s) => !fragmentos.some((f) => f.seccion === s)),
  consultas_rag,
  fragmentos,
  abstencion_normalizada: Boolean(d.abstencion_normalizada),
  cita_agregada: Boolean(d.cita_agregada),
  trace_id: $('Entrada desde Manager').first().json.trace_id ?? null,
  error: null
} }];
